import numpy as np
t=df['t'].values; A=df['A'].values; y=df['dA_dt'].values
tt=(t-5)/5
def fit(n,deg=6,extra=False):
    cols=[tt**i for i in range(deg)]+[tt**i*A**n for i in range(deg)]
    X=np.column_stack(cols)
    c=np.linalg.lstsq(X,y,rcond=None)[0]
    return np.mean((y-X@c)**2)/np.var(y)
for n in np.arange(2.5,3.6,0.05):
    print(round(n,2), f"{fit(n):.3e}")
